<template><div :class="isAuthenticatedStudent?'':'min-h-screen flex flex-col'"><AppNavbar v-if="!isAuthenticatedStudent"/><main class="flex-1 bg-[var(--surface-page)] py-8 sm:py-10"><div v-if="loading" class="mx-auto max-w-5xl px-4"><div class="h-[460px] animate-pulse rounded-3xl bg-white"></div></div><div v-else-if="error" class="mx-auto max-w-3xl px-4"><div class="rounded-2xl border border-red-200 bg-red-50 p-5 text-red-700">{{ error }}</div></div><div v-else-if="course" class="mx-auto max-w-6xl px-4 sm:px-6 lg:px-8"><nav class="mb-4 flex items-center gap-2 text-xs font-semibold text-slate-400" aria-label="Breadcrumb"><router-link to="/cursos" class="hover:text-[var(--brand-primary)]">Catálogo</router-link><span>/</span><span class="text-slate-600">{{ course.category }}</span></nav><div class="premium-card overflow-hidden"><div class="grid lg:grid-cols-[1.35fr_.65fr]"><div class="min-w-0"><div class="relative"><CourseCover :course="course" ratio="16/9" fit="cover" loading="eager" img-test-id="course-detail-cover-img" fb-test-id="course-detail-cover-fallback"/><div class="absolute inset-x-0 bottom-0 h-28 bg-gradient-to-t from-slate-950/55 to-transparent"></div><span class="absolute bottom-4 left-5 rounded-full bg-white/95 px-3 py-1 text-[10px] font-black uppercase tracking-[.13em] text-slate-700 shadow">{{ course.code }}</span></div><div class="p-6 sm:p-8"><p class="premium-kicker">{{ course.category }}</p><h1 class="mt-2 text-2xl font-bold tracking-tight text-slate-900 sm:text-3xl">{{ course.name }}</h1><p class="mt-3 text-sm leading-7 text-slate-500 sm:text-base">{{ course.description }}</p><div class="mt-6 grid grid-cols-2 gap-3 sm:grid-cols-4"><div v-for="info in courseInfo" :key="info.label" class="rounded-2xl border border-slate-100 bg-slate-50/70 p-3"><span class="block text-[10px] font-bold uppercase tracking-wider text-slate-400">{{ info.label }}</span><span class="mt-1 block text-sm font-bold text-slate-800">{{ info.value }}</span></div></div><div v-if="course.prerequisite" class="mt-7 rounded-2xl border border-slate-100 bg-white p-4"><h3 class="text-sm font-bold text-slate-800">Pré-requisitos</h3><p class="mt-1 text-sm leading-6 text-slate-500">{{ course.prerequisite }}</p></div></div></div><aside class="border-t border-slate-100 bg-slate-50/65 p-6 lg:border-l lg:border-t-0 sm:p-8"><div class="lg:sticky lg:top-28"><p class="text-[10px] font-bold uppercase tracking-[.15em] text-slate-400">Investimento</p><p class="mt-2 text-3xl font-black tracking-tight text-slate-900">{{ formatPrice(course.price) }}</p><p class="mt-1 text-sm text-slate-500">{{ course.carga_horaria }}h de conteúdo certificado</p><div class="my-6 h-px bg-slate-200"></div><button v-if="!authStore.isAuthenticated" @click="goToLogin" class="w-full rounded-xl px-4 py-3 text-sm font-bold text-white shadow-md" :style="{background:'var(--brand-primary)'}">{{ course.price>0?'Entrar para comprar':'Entrar para começar' }}</button><div v-else-if="enrollmentLoading" class="py-3 text-center text-sm text-slate-400">Carregando matrícula...</div><router-link v-else-if="courseEnrollment?.status==='CONFIRMADA'||courseEnrollment?.status==='CONCLUIDA'" :to="`/courses/${course.id}/learn`" class="block w-full rounded-xl bg-emerald-600 px-4 py-3 text-center text-sm font-bold text-white shadow-md hover:bg-emerald-700">Acessar curso</router-link><button v-else :disabled="purchasing" @click="startPurchase" class="w-full rounded-xl px-4 py-3 text-sm font-bold text-white shadow-md disabled:opacity-60" :style="{background:'var(--brand-primary)'}">{{ purchasing?purchaseLoadingText:purchaseButtonText }}</button><p v-if="purchaseError" class="mt-3 text-center text-xs font-medium text-red-600">{{ purchaseError }}</p><div v-if="!courseEnrollment" class="mt-5 rounded-xl border border-slate-200 bg-white p-3 text-center text-xs leading-5 text-slate-500"><template v-if="course.price>0"><span class="font-bold text-slate-700">Pagamento seguro</span><br>Pix, boleto ou cartão</template><template v-else><span class="font-bold text-emerald-700">Acesso liberado sem pagamento</span></template></div><p v-if="!authStore.isAuthenticated" class="mt-5 text-center text-xs text-slate-500">Já tem conta? <router-link :to="loginWithRedirect" class="font-bold text-[var(--brand-primary)]">Entre</router-link> ou <router-link :to="registerWithRedirect" class="font-bold text-[var(--brand-primary)]">cadastre-se</router-link></p></div></aside></div></div></div></main><footer v-if="!isAuthenticatedStudent" class="bg-slate-950 py-6 text-center text-sm text-white/55">{{ tenantStore.name||'Plataforma de Cursos' }}</footer></div></template>
<script setup>import{computed,onMounted,ref}from'vue';import{useRoute,useRouter}from'vue-router';import{useAuthStore}from'../stores/auth';import{useTenantStore}from'../stores/tenant';import{fetchCourse}from'../api/courses';import{purchaseCourse,getMyEnrollments,createCheckout}from'../api/enrollments';import AppNavbar from'../components/AppNavbar.vue';import CourseCover from'../components/CourseCover.vue';const route=useRoute(),router=useRouter(),authStore=useAuthStore(),tenantStore=useTenantStore();const isAuthenticatedStudent=computed(()=>authStore.isAuthenticated&&authStore.userRole?.toLowerCase()==='student');const course=ref(null),loading=ref(true),error=ref(''),purchasing=ref(false),purchaseError=ref(''),enrollments=ref([]),enrollmentLoading=ref(false);const redirectPath=computed(()=>route.fullPath),loginWithRedirect=computed(()=>({path:'/login',query:{redirect:redirectPath.value}})),registerWithRedirect=computed(()=>({path:'/register',query:{redirect:redirectPath.value}})),courseEnrollment=computed(()=>enrollments.value.find(e=>e.course_id===course.value?.id));const courseInfo=computed(()=>[{label:'Carga horária',value:`${course.value?.carga_horaria||0}h`},{label:'Modalidade',value:course.value?.modality||'—'},{label:'Tipo',value:course.value?.type||'Formação'},{label:'Código',value:course.value?.code||'—'}]);function formatPrice(price){if(price===0||price===null)return'Gratuito';return new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(price)}function goToLogin(){router.push({path:'/login',query:{redirect:redirectPath.value}})}async function startPurchase(){purchaseError.value='';purchasing.value=true;try{const{data}=await purchaseCourse(course.value.id,'UNDEFINED');if(!data.payment){await router.push(`/courses/${course.value.id}/learn`);return}const checkout=await createCheckout(data.payment.id);window.location.href=checkout.data.checkout_url}catch(err){purchaseError.value=err.response?.data?.detail||'Erro ao iniciar a compra. Tente novamente.';purchasing.value=false}}const purchaseButtonText=computed(()=>Number(course.value?.price||0)<=0?'Começar curso grátis':courseEnrollment.value?.status==='PENDENTE'?'Finalizar pagamento':courseEnrollment.value?.status==='CANCELADA'?'Comprar novamente':'Comprar agora');const purchaseLoadingText=computed(()=>Number(course.value?.price||0)<=0?'Liberando acesso...':'Redirecionando...');onMounted(async()=>{try{await authStore.initializeUser();const{data}=await fetchCourse(route.params.id);course.value=data;if(authStore.isAuthenticated){enrollmentLoading.value=true;enrollments.value=(await getMyEnrollments()).data}}catch(err){error.value=err.response?.data?.detail||'Curso não encontrado.'}finally{loading.value=false;enrollmentLoading.value=false}})</script>
